        --    text = localize("战略物资"),
        --    redPointStrNode = Constants.RedPointConst.GrowthFund,
        --    --selectImgPath = "uiatlas/ResidentEvent/common/resident_common_btn_icon.png",
        --    func = function()
        --        self:RefreshUI(Constants.UITypeIds.GrowthFundDialog)
        --    end
        --},
        [3] = {
            text = localize("每日签到"),
            --textColor = {
            --    default = "#C5C5C5",
            --    selected = "#000000"
            --},
            selectImgPath = "Arts/Icons/HomeLabel/tab_ico_everyday.png",
            func = function()
                self:Sign(Constants.UITypeIds.PlayerSignDialog)
            end
        },
    }
    local node = GetLuaBehaviour(self.CommonTabToggleLeft.gameObject, "Game.Behaviours.CommonTabToggleLeft")
