function ResidentEventMain:GetTabIndex(openId)
    for i, v in pairs(Groups) do
        if checkInt(openId) == v.prefabId then
            return v.id
        end
    end
end

---RefreshUI
---刷新ui的逻辑
---@param openType number
function ResidentEventMain:RefreshUI(openType)
    if openType == Constants.UITypeIds.GrowthFundDialog then
        xRecord.record('7-004')
    elseif openType == Constants.UITypeIds.StoreMonthCard then
        xRecord.record('9-019')
    end
    if self.openId == openType then
        return
    end
    UIRaycastBlocker:AddCondition("ResidentEventMainUI")
    xTry(function()
        cs_coroutine.start(function()
            ---执行建立页面
            if not isNull(self.openId) then
                ---不为空的情况下，将的状态的处理
                local node = self.nodeGos[tostring(self.openId)]
                if not isNull(node.go) then
                    KTool.SetActive(node.go, false)
                end
            end
            if self.nodeGos[tostring(openType)] then
                local node = self.nodeGos[tostring(openType)]
                if not isNull(node.go) and node.scr then
                    KTool.SetActive(node.go, true)
                    node.scr:RefreshSelf({ openId = openType })
                end
            else
                local row = UIModule.GetPrefabVoByRefId(openType)
                local path = row:Get("path")
                ---@type Engine.Modules.AbstractResourceLoader
                local loader = ResourceModule.LoadBundleAsync(path, nil, true)
                while not loader.IsSuccess do
                    cs_coroutine.yield_return(Yielders.EndOfFrame)
                end
                if loader.IsSuccess then
                    -- local go = GameObject.Instantiate(loader.ResultObject)
                    local go = loader:Instantiate()
                    loader:Release()
                    
                    if not KTool.IsNull(go) and not KTool.IsNull(self.UIContainer) then
                        go.name = string.stripExtension(string.stripFileName(path))
                        KTool.SetParent(go, self.UIContainer.gameObject, false)
                    end
                    local t = Groups[openType]
                    local scr = CfUtils.GetLuaScr(go, t.scrPath)
                    -- table.insert(self.loaders, loader)
                    local node = {
                        go = go,
                        scr = scr,
                    }
                    self.nodeGos[tostring(openType)] = node
                    local atlasTagStr = parse_string(row, "atlasTag")
                    if not string.isEmpty(atlasTagStr) then
                        local atlasTagList = parse_strings(atlasTagStr)
                        if next(atlasTagList) then
                            -- SpriteAtlasManager.Instance():RetainAtlases(atlasTagList, loader)
                        end
                    end
                    if not isNull(node.go) and node.scr then
                        KTool.SetActive(node.go, true)
                        node.scr:RefreshSelf({ openId = openType })
                    end
                else
                    loader:Release(true)
                    loader = nil
                end
            end
            self.openId = openType
            UIRaycastBlocker:RemoveCondition("ResidentEventMainUI")
        end)
    end, function()
        UIRaycastBlocker:RemoveCondition("ResidentEventMainUI")
    end)

    ---是否需要修改当前的标签条
    --StoreUtils.RefreshNavigatorBar(openType)

end

---签到
function ResidentEventMain:Sign(openType)
    UIRaycastBlocker:AddCondition("ResidentEventMainUI")
    cs_coroutine.start(function()
        KCookie.RemoveAllListener(Constants.UICacheDataKeys.IS_FIRST_ENTER_SIGN)
        KCookie.Set(Constants.UICacheDataKeys.OPEN_SIGN_VIEW, 1)
        local isFirstEnterGame = KCookie.Get(Constants.UICacheDataKeys.IS_FIRST_ENTER_SIGN)
        if isNull(isFirstEnterGame) then
            local isSuccess = 0
            local responseData = {}
            ----开始处理数据
            local dateObj = date()
            local curDay = dateObj:getday()
            local curHour = dateObj:gethours()
            GameUtils.Request(Interfaces.SignHome, {}, function(request, response)
                xpcall(function()
                    if checkNumber(response.errCode) == 0 then
                        responseData = checkTable(response.data)
                        KCookie.Set(Constants.UICacheDataKeys.IS_FIRST_ENTER_SIGN, 1)
                        --local t = timestamp_to_time(TimeZoneUtils.UtcSeconds)
                        --local curDay = t.day ---当前在这个月中的天值
                        local singData = checkTable(responseData.ftLoginInfo)
                        local giftBoxData = checkTable(responseData.ftLoginRewardInfo)
                        ---消耗信息
                        local consumeInfo = checkTable(responseData.ftLoginCumulativeInfo)
                        local resetTime = 5
                        local needPopupSign = 0
                        local curDaySignData
                        for _, v in pairs(singData) do
                            if checkNumber(v.day) == curDay - 1 and checkNumber(v.hasDrawn) == 0 and curHour < resetTime then
                                curDaySignData = v
                                needPopupSign = 1
                                break
                            elseif checkNumber(v.day) == curDay and checkNumber(v.hasDrawn) == 0 and curHour >= resetTime then
                                ---当前天并且未签，请求登录签，然后才会弹出签到界面
                                curDaySignData = v
                                needPopupSign = 1
                                break
                            end
                        end
                        if needPopupSign == 1 then
                            GameUtils.Request(Interfaces.SignRequest, {}, function(req, resp)
                                if checkNumber(resp.errCode) == 0 then
                                    ---请求签到完成
                                    if curDaySignData then
                                        curDaySignData.hasDrawn = 2 ---表示是已签到了更新下数据,2用来做动画
                                    end
                                    local responseData = checkTable(resp.data)
                                    GoodsUtils.DrawRewards(checkTable(responseData.rewards))
                                    UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = checkTable(responseData.rewards) } })
                                    isSuccess = 1
                                    --UIModule.OpenDialog({ id = Constants.UITypeIds.PlayerSignDialog, parameters = { signData = singData, giftData = giftBoxData, curDay = curDay, rewards = responseData.rewards, reIssueNum = checkNumber(responseData.reIssueNum), consumeInfo = consumeInfo } })
                                else
                                    isSuccess = 1
                                    UIRaycastBlocker:RemoveCondition("ResidentEventMainUI")
                                end
                            end)
                        else
                            isSuccess = 1
                            --UIModule.OpenDialog({ id = Constants.UITypeIds.PlayerSignDialog, parameters = { signData = singData, giftData = giftBoxData, curDay = curDay, rewards = responseData.rewards, reIssueNum = checkNumber(responseData.reIssueNum), consumeInfo = consumeInfo } })
                        end
                    end
                end, function(e)
                    UIRaycastBlocker:RemoveCondition("ResidentEventMainUI")
                    printError()
                end)
            end)
            while isSuccess == 0 do
                coroutine.yield()
            end
            local singData = checkTable(responseData.ftLoginInfo)
            local giftBoxData = checkTable(responseData.ftLoginRewardInfo)
            ---消耗信息
            local consumeInfo = checkTable(responseData.ftLoginCumulativeInfo)
            ---可以弹出签到页面了
            cs_coroutine.yield_return(self:AsyncSign({ signData = singData, giftData = giftBoxData, curDay = curDay, rewards = responseData.rewards, reIssueNum = checkNumber(responseData.reIssueNum), consumeInfo = consumeInfo }, openType))
        end
        UIRaycastBlocker:RemoveCondition("ResidentEventMainUI")
    end)
end

function ResidentEventMain:AsyncSign(parameters, openType)
    if not isNull(self.openId) then
        ---不为空的情况下，将的状态的处理
        local node = self.nodeGos[tostring(self.openId)]
        if not isNull(node.go) then
            KTool.SetActive(node.go, false)
        end
    end
    if self.nodeGos[tostring(openType)] then
        local node = self.nodeGos[tostring(openType)]
        if not isNull(node.go) and node.scr then
            KTool.SetActive(node.go, true)
            node.scr:Initialize(parameters)
            cs_coroutine.yield_return(node.scr:RefreshSelf({ openId = openType }))
        end
    else
        local row = UIModule.GetPrefabVoByRefId(openType)
        local path = row:Get("path")
        ---@type Engine.Modules.AbstractResourceLoader
        local loader = ResourceModule.LoadBundleAsync(path, nil, true)
        while not loader.IsSuccess do
            cs_coroutine.yield_return(Yielders.EndOfFrame)
        end
        if loader.IsSuccess then
            -- local go = GameObject.Instantiate(loader.ResultObject)
            local go = loader:Instantiate()
            loader:Release()

            if not KTool.IsNull(go) and not KTool.IsNull(self.UIContainer) then
                go.name = string.stripExtension(string.stripFileName(path))
                KTool.SetParent(go, self.UIContainer.gameObject, false)
            end
            local t = Groups[openType]
            local scr = CfUtils.GetLuaScr(go, t.scrPath)
            -- table.insert(self.loaders, loader)
            local node = {
                go = go,
                scr = scr,
            }
            self.nodeGos[tostring(openType)] = node
            local atlasTagStr = parse_string(row, "atlasTag")
            if not string.isEmpty(atlasTagStr) then
                local atlasTagList = parse_strings(atlasTagStr)
                if next(atlasTagList) then
                    -- SpriteAtlasManager.Instance():RetainAtlases(atlasTagList, loader)
                end
            end
            if not isNull(node.go) and node.scr then
                KTool.SetActive(node.go, true)
                node.scr:Initialize(parameters)
                cs_coroutine.yield_return(node.scr:RefreshSelf({ openId = openType }))
            end
        else
            loader:Release(true)
            loader = nil
        end
    end
    self.openId = openType
end

function ResidentEventMain:OnFinalize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        self.nodeGos = nil
        -- if self.loaders then
        --     for i, v in pairs(self.loaders) do
        --         v:Release()
        --     end
        --     self.loaders = nil
        -- end
        self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
        self:Delete()
        self = nil --lua层的gc需要
    end))
    return coWait
end

return ResidentEventMain